import{_ as a,o as e,c as l,a2 as o}from"./chunks/framework.z3u3TMv0.js";const u=JSON.parse('{"title":"第一次使用","description":"","frontmatter":{},"headers":[],"relativePath":"manual/getting-started.md","filePath":"manual/getting-started.md","lastUpdated":1786093688000}'),i={name:"manual/getting-started.md"};function r(s,t,n,d,c,h){return e(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="第一次使用" tabindex="-1">第一次使用 <a class="header-anchor" href="#第一次使用" aria-label="Permalink to &quot;第一次使用&quot;">​</a></h1><p>目标：完成「配好模型 → 有一张角色卡 → 发出第一条消息」。</p><h2 id="步骤总览" tabindex="-1">步骤总览 <a class="header-anchor" href="#步骤总览" aria-label="Permalink to &quot;步骤总览&quot;">​</a></h2><ol><li>打开 App，进入底部 <strong>设置</strong>。</li><li>配置 <a href="./model-link">模型连接</a> 并测连成功，设为默认。</li><li>底部 <strong>角色卡</strong> → 导入或创建角色。</li><li>从角色开聊，发送一条消息。</li></ol><h2 id="_1-配置-ai-模型连接" tabindex="-1">1. 配置 AI（模型连接） <a class="header-anchor" href="#_1-配置-ai-模型连接" aria-label="Permalink to &quot;1. 配置 AI（模型连接）&quot;">​</a></h2><p>路径：<strong>设置 → 模型连接 → 新建</strong></p><ol><li>填写名称（可默认）。</li><li>选择 <strong>模型平台</strong>（OpenAI、DeepSeek、自定义 OpenAI 协议等）。</li><li>填写 <strong>API 密钥</strong>（本地服务通常可留空或填占位）。</li><li>确认 <strong>Base URL</strong>（自定义协议必填，如 <code>https://api.xxx.com/v1</code>）。</li><li>选择或输入 <strong>模型</strong> ID。</li><li>点 <strong>测试</strong>；成功后再保存，并在列表中设为 <strong>默认</strong>。</li></ol><p>失败时点「查看详情」，对照 <a href="./errors">错误代码排错</a>。</p><div class="tip custom-block"><p class="custom-block-title">截图</p><ul><li><code>manual/screenshots/01-settings-home.png</code> — 设置首页（含「模型连接」）</li><li><code>manual/screenshots/02-model-link-create.png</code> — 新建模型连接表单</li><li><code>manual/screenshots/03-model-link-test-ok.png</code> — 测连成功</li></ul></div><h2 id="_2-导入第一张角色卡" tabindex="-1">2. 导入第一张角色卡 <a class="header-anchor" href="#_2-导入第一张角色卡" aria-label="Permalink to &quot;2. 导入第一张角色卡&quot;">​</a></h2><p>路径：底部 <strong>角色卡</strong> → 创建 / 导入</p><table tabindex="0"><thead><tr><th>方式</th><th>操作</th></tr></thead><tbody><tr><td>文件</td><td>选择 PNG（酒馆卡）或 JSON</td></tr><tr><td>相册</td><td>从相册选 PNG 卡图</td></tr><tr><td>链接</td><td>粘贴角色卡下载地址</td></tr><tr><td>示例</td><td>按引导导入内置样卡（若有）</td></tr></tbody></table><p>单卡会先进入 <strong>预览</strong>：确认「新建」或「同名更新」，可选是否把卡内世界书 / 正则复制到全局。点确认后才真正入库。</p><div class="tip custom-block"><p class="custom-block-title">截图</p><ul><li><code>manual/screenshots/04-chara-tab.png</code> — 角色卡 Tab 列表</li><li><code>manual/screenshots/05-chara-import-preview.png</code> — 导入预览与确认</li></ul></div><h2 id="_3-开始聊天" tabindex="-1">3. 开始聊天 <a class="header-anchor" href="#_3-开始聊天" aria-label="Permalink to &quot;3. 开始聊天&quot;">​</a></h2><ol><li>在角色卡上开聊（或从 <strong>聊天</strong> Tab 进入已有会话）。</li><li>若有多条开场白，按提示选择。</li><li>输入消息发送；回复支持流式显示。</li><li>未配置模型时，聊天页会提示先去配置 AI。</li></ol><div class="tip custom-block"><p class="custom-block-title">截图</p><ul><li><code>manual/screenshots/06-chat-first-message.png</code> — 对话页首条往返</li></ul></div><h2 id="_4-建议接着做" tabindex="-1">4. 建议接着做 <a class="header-anchor" href="#_4-建议接着做" aria-label="Permalink to &quot;4. 建议接着做&quot;">​</a></h2><ul><li><a href="./chat">聊天</a>：续写、重生成、会话级模型 / 世界书</li><li><a href="./backup">备份与存档</a>：尽快做一次全量备份</li><li>使用本地电脑模型：<a href="/ultra_guides/quickstart">30 分钟通关</a></li></ul>',19)])])}const g=a(i,[["render",r]]);export{u as __pageData,g as default};
